INSERT INTO kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, prerequisite_concepts, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, skills_assessed, source, year, exam_body, related_question_ids, stem, options, correct_option, explanation, lifecycle_state, empirical_stats) VALUES
('mathematics_0031', 'Mathematics', 'Probability', 'Simple Probability', NULL, '[{"weight": 1, "conceptId": "otm0ur"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "B", "explanation": "3/10 = 6/20 is P(E1), the probability of picking a multiple of 3 (E1 has 6 elements: 3,6,9,12,15,18) — the student used the wrong set, confusing E1 with E2.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "1/4 = 5/20 is P(in E2), i.e. the probability of being a multiple of 4 — the student forgot the word ''not'' and answered the complement''s complement.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "1/20 corresponds to P(E1 ∩ E2), i.e. multiples of 12 in U (just {12}) — the student mistakenly intersected E1 and E2 instead of taking the complement of E2 alone.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If U = {x : x is an integer and 1 \(\leq\) x \(\leq\) 20} E\(_1\) = {x : x is a multiple of 3} E\(_2\) = {x : x is a multiple of 4} and an integer is picked at random from U, find the probability that it is not in E\(_2\)', '[{"label": "A", "text": "3/4", "isCorrect": true}, {"label": "B", "text": "3/10", "isCorrect": false}, {"label": "C", "text": "1/4", "isCorrect": false}, {"label": "D", "text": "1/20", "isCorrect": false}]'::jsonb, 'A', 'U = {1,...,20} has 20 elements. E2 (multiples of 4) = {4,8,12,16,20}, so |E2| = 5, leaving 20 - 5 = 15 elements not in E2. P(not in E2) = 15/20 = 3/4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0032', 'Mathematics', 'Logarithms', 'Laws of Logarithms', NULL, '[{"weight": 1, "conceptId": "q380e4"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "8 results from dropping the negative sign on the exponent (5^(3log_5 2) = 2^3 = 8) and then forgetting to multiply by the second term, treating it as if it equalled 1.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "2 is the value a student gets by mis-cancelling the log identity, e.g. treating 5^(-3log_5 2) as -3 × 5^(log_5 2) = -6 and 2^(2log_2 3) as 2 × log_2 3, then combining incorrectly rather than applying a^(log_a b)=b cleanly.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "1/8 (also mis-scraped as ''1'') is just the first factor 5^(-3log_5 2) evaluated correctly, with the second factor 2^(2log_2 3)=9 forgotten entirely, i.e. the multiplication step was skipped.", "misconceptionId": "rushed_under_pressure"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Evaluate 5-\(^{3log_52}\) x 2\(^{2log_23}\)', '[{"label": "A", "text": "8", "isCorrect": false}, {"label": "B", "text": "1", "isCorrect": true}, {"label": "C", "text": "2", "isCorrect": false}, {"label": "D", "text": "1", "isCorrect": false}]'::jsonb, 'B', 'Using a^(log_a b) = b: 5^(-3log_5 2) = (5^(log_5 2))^(-3) = 2^(-3) = 1/8. Also 2^(2log_2 3) = (2^(log_2 3))^2 = 3^2 = 9. Multiplying: (1/8) × 9 = 9/8 = 1 1/8 (option B, shown as a fraction in the original that scraped as ''1'').', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0033', 'Mathematics', 'Percentages', 'Profit and Loss', NULL, '[{"weight": 1, "conceptId": "r9oudo"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "60 results from computing the loss as (50,000-25,000+10,000)/50,000 or otherwise mixing Femi''s profit amount directly into Audu''s loss calculation instead of first isolating Femi''s cost price.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "40 is simply Femi''s profit percentage (40%) copied across as if it were Audu''s loss percentage, confusing the two different percentages in the problem.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "20 comes from treating N10,000 as 20% of Audu''s N50,000 directly, skipping the required step of first finding Femi''s cost price via the 40% profit relation.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Audu bought an article for N50,000 and sold it to Femi at a loss of x%. Femi later sold the article to Oche at a profit of 40%. If Femi made a profit of N10,000, find the value of x.', '[{"label": "A", "text": "60", "isCorrect": false}, {"label": "B", "text": "50", "isCorrect": true}, {"label": "C", "text": "40", "isCorrect": false}, {"label": "D", "text": "20", "isCorrect": false}]'::jsonb, 'B', 'Femi''s profit of N10,000 is 40% of his cost price, so his cost price (= Audu''s selling price) = 10,000/0.4 = N25,000. Audu bought at N50,000 and sold at N25,000, a loss of 25,000/50,000 = 50%, so x = 50.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0034', 'Mathematics', 'Binary operations', 'Identity and Inverse Elements', NULL, '[{"weight": 1, "conceptId": "cuzren"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "p wrongly assumes every element is its own inverse, without solving p*q=0 for q at all.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "p-1 comes from mishandling the equation p+q-pq=0, e.g. dividing incorrectly and dropping the pq term''s effect on isolating q.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "p/(p+1) results from a sign error when rearranging p + q - pq = 0 to q(1-p) = -p, flipping the sign of the (1-p) factor to (1+p) instead.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Find the inverse of p under the binary operation * defined by p*q = p + q - pq, where p and q are real numbers and zero is the identity', '[{"label": "A", "text": "p", "isCorrect": false}, {"label": "B", "text": "p -1", "isCorrect": false}, {"label": "C", "text": "p/(p-1)", "isCorrect": true}, {"label": "D", "text": "p/(p+1)", "isCorrect": false}]'::jsonb, 'C', 'With identity 0, the inverse q of p satisfies p*q = 0: p + q - pq = 0, so q(1-p) = -p, giving q = -p/(1-p) = p/(p-1).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0035', 'Mathematics', 'Quadratic equations', 'Sum and Product of Roots', NULL, '[{"weight": 1, "conceptId": "un5z3j"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "-5/3 is just the sum of roots α+β given directly, without dividing by the product αβ to complete the 1/α+1/β formula.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "-2/3 is the product of roots αβ mistaken for the required answer, confusing which coefficient ratio the question needs.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "1/2 results from a sign error, computing (α+β)/(αβ) as (5/3)/(-2/3)×(-1) inconsistently or mixing up the signs of b and c in the sum/product formulas.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If α and β are the roots of the equation 3x\(^2\) + 5x - 2 = 0, find the value of 1/α + 1/β', '[{"label": "A", "text": "-5/3", "isCorrect": false}, {"label": "B", "text": "-2/3", "isCorrect": false}, {"label": "C", "text": "1/2", "isCorrect": false}, {"label": "D", "text": "5/2", "isCorrect": true}]'::jsonb, 'D', 'For 3x^2+5x-2=0, sum of roots α+β = -5/3 and product αβ = -2/3. So 1/α+1/β = (α+β)/(αβ) = (-5/3)/(-2/3) = 5/2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0036', 'Mathematics', 'Coordinate geometry', 'Perpendicular Lines', NULL, '[{"weight": 1, "conceptId": "qip98q"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "B", "explanation": "-3/4 comes from using the parallel-line condition (setting the two slopes equal, m1=m2) instead of the perpendicular condition, then solving 4/3=1/K incorrectly with a sign flip.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "3/4 is the reciprocal of the correct answer with the sign error omitted — the negative reciprocal rule was applied as a plain reciprocal.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "4/3 is simply the slope of the first line (m1) copied as the answer, without ever applying the perpendicularity condition to find K.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', '3y = 4x - 1 and Ky = x + 3 are equations of two straight lines. If the two lines are perpendicular to each other, find K.', '[{"label": "A", "text": "-\\(\\frac{4}{3}\\)", "isCorrect": true}, {"label": "B", "text": "-\\(\\frac{3}{4}\\)", "isCorrect": false}, {"label": "C", "text": "\\(\\frac{3}{4}\\)", "isCorrect": false}, {"label": "D", "text": "\\(\\frac{4}{3}\\)", "isCorrect": false}]'::jsonb, 'A', '3y=4x-1 gives slope m1=4/3. Ky=x+3 gives slope m2=1/K. For perpendicular lines m1×m2=-1: (4/3)(1/K)=-1, so K = -4/3.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0037', 'Mathematics', 'Loci', 'Locus of Points Equidistant from Two Fixed Points', NULL, '[{"weight": 1, "conceptId": "1zxoi6"}]'::jsonb, '{}', 1, 'recall', 90, 'low', 'light', '[{"option": "A", "explanation": "A straight line is too vague/incomplete an answer — it omits the defining property (perpendicular bisector of PQ specifically) that distinguishes this locus from any line.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "A circle is the locus for a point at a *fixed* distance from a single point, not equidistant from two points — the two locus rules have been confused.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "The bisector of angle PXQ confuses this locus with the angle-bisector locus rule (equidistant from two lines), not the equidistant-from-two-points rule.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'if P and Q are fixed points and X is a point which moves so that XP = XQ, the locus of X is', '[{"label": "A", "text": "A straight line", "isCorrect": false}, {"label": "B", "text": "a circle", "isCorrect": false}, {"label": "C", "text": "the bisector of angle PXQ", "isCorrect": false}, {"label": "D", "text": "the perpendicular bisector of PQ", "isCorrect": true}]'::jsonb, 'D', 'A point X moving so that it stays equidistant from two fixed points P and Q (XP=XQ) traces the perpendicular bisector of the line segment PQ — this is a standard locus theorem.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0038', 'Mathematics', 'Applications of integration', 'Volume of Revolution', NULL, '[{"weight": 1, "conceptId": "5fdhjk"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "7π results from an incorrect integration limit, e.g. integrating (y+1) from 0 to 3 instead of the correct -1 to 3, dropping part of the solid.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "15π/2 comes from using the disk method with x=y^2-1 mistakenly treated as the radius directly (forgetting to invert to x=√(y+1)) and mis-setting the bounds.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "17π/2 arises from a small arithmetic slip evaluating (y+1)^2/2 at the bounds, e.g. computing 16/2 as 17/2 or mishandling the lower limit.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A bowl is designed by revolving completely the area enclosed by y = x\(^2\) - 1, y = 3, and x ≥ 0 around the y-axis. What is the volume of this bowl?', '[{"label": "A", "text": "7π cubic units", "isCorrect": false}, {"label": "B", "text": "15π/2 cubic units", "isCorrect": false}, {"label": "C", "text": "8π cubic units", "isCorrect": true}, {"label": "D", "text": "17π/2 cubic units", "isCorrect": false}]'::jsonb, 'C', 'The region (x≥0) between y=x^2-1 and y=3 revolved about the y-axis gives radius x=√(y+1) at height y, from y=-1 to y=3. Volume = π∫[from -1 to 3] x^2 dy = π∫(y+1)dy = π[(y+1)^2/2] from -1 to 3 = π(16/2 - 0) = 8π cubic units.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0039', 'Mathematics', 'Measures of dispersion', 'Range and Mode', NULL, '[{"weight": 1, "conceptId": "1eyy37"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "B", "explanation": "14 results from an off-by-one counting error on the mode''s frequency-based value, or from using 9 (the second most frequent value, appearing 5 times) mistaken for the mode: 6+9 minus a slip = 14 region confusion between the two most frequent values.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "12 comes from doubling the range (6×2) instead of adding the mode, misapplying what ''sum of range and mode'' means.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "10 is just the mode alone, with the range term forgotten entirely from the sum.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Find the sum of the range and the mode of the set of numbers 10, 9, 10, 9, 8, 7, 7, 10, 8, 10, 8, 4, 6, 9, 10, 9, 10, 9, 7, 10, 6, 5', '[{"label": "A", "text": "16", "isCorrect": true}, {"label": "B", "text": "14", "isCorrect": false}, {"label": "C", "text": "12", "isCorrect": false}, {"label": "D", "text": "10", "isCorrect": false}]'::jsonb, 'A', 'The data set has minimum 4 and maximum 10, so range = 10-4 = 6. The most frequent value is 10, appearing 7 times, so mode = 10. Sum = 6+10 = 16.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0040', 'Mathematics', 'Data collection and presentation', 'Pie Chart Angles', NULL, '[{"weight": 1, "conceptId": "q9ah8r"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "10° results from dividing the frequency by 360 instead of multiplying the fraction of the total by 360 (i.e. computing 40/360×10 or a similar inverted setup).", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "16° could come from mistakenly using 90 (a quarter circle) instead of 360 as the base, e.g. (40/240)×90 rounded, or a mis-keyed total.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "40° is simply the raw frequency for face 4 taken directly as the angle, skipping the proportion-to-360° conversion entirely.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Given that the various faces of a fair dice 1, 2, 3, 4, 5, 6 appeared 30, 43, 54, 40, 41, 32 times respectively in a single toss. Picture the figures as being represented in a simple table with number (X) against frequency (f). If a pie chart is used to depict the data, the angle corresponding to 4 is?', '[{"label": "A", "text": "10°", "isCorrect": false}, {"label": "B", "text": "16°", "isCorrect": false}, {"label": "C", "text": "40°", "isCorrect": false}, {"label": "D", "text": "60°", "isCorrect": true}]'::jsonb, 'D', 'Total frequency = 30+43+54+40+41+32 = 240. The angle for face 4 (frequency 40) is (40/240)×360° = 60°.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0041', 'Mathematics', 'Probability', 'Independent Events', NULL, '[{"weight": 1, "conceptId": "vhs1k3"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "0.30 is just P(X∪Y) - P(X) = 0.7-0.4 computed directly, ignoring the independence correction term -P(X)P(Y) in the addition rule.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "0.57 results from treating the events as mutually exclusive-with-error or mis-solving 0.7=0.4+P(Y)-0.4P(Y) with an arithmetic slip, e.g. dividing 0.3 by 0.4+0.6≈ miscomputed 0.6.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "1.80 comes from ignoring the independence term and simply solving 0.7=0.4+P(Y)+0.4P(Y) with a sign error, over-adding instead of subtracting the overlap.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'X and Y are two events. The probability of X or Y is 0.7 and that of X is 0.4. If X and Y are independent, find the probability of Y.', '[{"label": "A", "text": "0.30", "isCorrect": false}, {"label": "B", "text": "0.50", "isCorrect": true}, {"label": "C", "text": "0.57", "isCorrect": false}, {"label": "D", "text": "1.80", "isCorrect": false}]'::jsonb, 'B', 'For independent events, P(X∪Y) = P(X)+P(Y)-P(X)P(Y). So 0.7 = 0.4 + P(Y) - 0.4P(Y) = 0.4 + 0.6P(Y), giving 0.6P(Y) = 0.3, so P(Y) = 0.5.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0042', 'Mathematics', 'Percentages', 'Percentage Change', NULL, '[{"weight": 1, "conceptId": "mathpct1"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "480,000 comes from mistakenly doubling the population, as if a 2% increase meant multiplying by 2 instead of 1.02.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "249,600 results from applying simple (non-compound) growth incorrectly, e.g. 240,000 + 2×(2% of 240,000) = 240,000+9,600=249,600, missing the compounding effect on the second year.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "244,800 is 240,000 with only a single year''s 2% increase applied (240,000×1.02), forgetting that two full years (1998→2000) must be compounded.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If the population of a town was 240,000 in January 1998 and it increased by 2% each year, what would be the population of the town in January, 2000?', '[{"label": "A", "text": "480,000", "isCorrect": false}, {"label": "B", "text": "249,696", "isCorrect": true}, {"label": "C", "text": "249,600", "isCorrect": false}, {"label": "D", "text": "244,800", "isCorrect": false}]'::jsonb, 'B', 'From Jan 1998 to Jan 2000 is 2 years of compounding at 2% per year: 240,000 × 1.02^2 = 240,000 × 1.0404 = 249,696.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0043', 'Mathematics', 'Differentiation', 'Coefficients from Derivative Conditions', NULL, '[{"weight": 1, "conceptId": "aq6l6g"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "(1,3,1) swaps the values of b and c — correctly finding a=1 and b=1 from the derivative, but then misassigning which unknown gets the value 3 when solving a+b+c=5.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "(1,2,1) results from incorrectly solving a+b+c=5 as if b were still unknown to solve for, e.g. mis-substituting and getting b=2, c=1 instead of correctly using a=1,b=1 to find c=3.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "(2,1,1) comes from misreading the derivative matching step, e.g. setting 2a=1 (instead of 2a=2) so a wrongly comes out as... actually setting a=2 by mismatching 2x+1 terms, then leaving b=1 and solving for c=1 with an additional slip.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'The expression ax\(^2\) + bx + c equals 5 at x = 1. If its derivative is 2x + 1, what are the values of a, b, and c, respectively?', '[{"label": "A", "text": "1, 3, 1", "isCorrect": false}, {"label": "B", "text": "1, 2, 1", "isCorrect": false}, {"label": "C", "text": "2, 1, 1", "isCorrect": false}, {"label": "D", "text": "1, 1, 3", "isCorrect": true}]'::jsonb, 'D', 'The derivative of ax^2+bx+c is 2ax+b. Matching to 2x+1 gives 2a=2 so a=1, and b=1. Using ax^2+bx+c=5 at x=1: a+b+c=5, so 1+1+c=5, giving c=3. Hence (a,b,c) = (1,1,3).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0044', 'Mathematics', 'Permutations and combinations', 'Word Arrangement Permutations', NULL, '[{"weight": 1, "conceptId": "t6mjxk"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "11!/(9!2!) treats the word as if it only had one repeated letter (pattern for choosing 2 identical items among 11, like a simple combination formula), missing that there are three separate letters each repeated twice.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "11!/(9!2!2!) incorrectly mixes a 9! term (as if only 2 letters were fixed/distinct) with two 2! repeat corrections, miscounting which letters repeat and how many are free to arrange.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "11!/(2!2!) accounts for only two of the three repeated letters (e.g. M and A but forgetting T also repeats twice), an incomplete repeat count.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'In how many ways can the word MATHEMATICS be arranged?', '[{"label": "A", "text": "11!/(9! 2!)", "isCorrect": false}, {"label": "B", "text": "11!/(9! 2! 2!)", "isCorrect": false}, {"label": "C", "text": "11!/(2! 2! 2!)", "isCorrect": true}, {"label": "D", "text": "11!/(2! 2!)", "isCorrect": false}]'::jsonb, 'C', 'MATHEMATICS has 11 letters with repeats: M appears 2 times, A appears 2 times, T appears 2 times (H, E, I, C, S appear once each). The number of distinct arrangements is 11!/(2!2!2!).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0045', 'Mathematics', 'Applications of differentiation', 'Related Rates', NULL, '[{"weight": 1, "conceptId": "87au5b"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "2.50 m/s is off by a factor of 10, likely from a decimal-place slip when dividing 18/72.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "2.00 m/s could come from using the full-sphere volume formula V=(4/3)πr^3 inconsistently or mis-cancelling πr^2 terms, landing on a rounder but wrong value.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "0.20 m/s results from using r^2=90 or a similar miscomputation of 6^2 (e.g. treating it as 90 instead of 36) before dividing 18 by it.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If the volume of a hemisphere is increasing at a steady rate of 18π m\(^{3}\) s\(^{-1}\), at what rate is its radius changing when its is 6m?', '[{"label": "A", "text": "2.50m/s", "isCorrect": false}, {"label": "B", "text": "2.00 m/s", "isCorrect": false}, {"label": "C", "text": "0.25 m/s", "isCorrect": true}, {"label": "D", "text": "0.20 m/s", "isCorrect": false}]'::jsonb, 'C', 'Hemisphere volume V=(2/3)πr^3, so dV/dr=2πr^2. By the chain rule, dr/dt = (dV/dt)/(dV/dr) = 18π/(2π×6^2) = 18π/(72π) = 0.25 m/s.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0046', 'Mathematics', 'Number bases', 'Base Conversion', NULL, '[{"weight": 1, "conceptId": "be64x9"}]'::jsonb, '{}', 1, 'recall', 90, 'low', 'light', '[{"option": "B", "explanation": "106₈ comes from an arithmetic slip in the first division step, e.g. computing 8×8=63 instead of 64 and getting remainder 8 miscounted down to a wrong final digit sequence.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "71₈ simply copies the base-10 digits unchanged, as if no conversion were needed at all.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "17₈ comes from writing the remainders in the wrong order (top-down instead of bottom-up), reversing the digit sequence produced by repeated division.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Change 71\(_{10}\) to base 8', '[{"label": "A", "text": "107\\(_{8}\\)", "isCorrect": true}, {"label": "B", "text": "106\\(_{8}\\)", "isCorrect": false}, {"label": "C", "text": "71\\(_8\\)", "isCorrect": false}, {"label": "D", "text": "17\\(_8\\)", "isCorrect": false}]'::jsonb, 'A', '71 ÷ 8 = 8 remainder 7; 8 ÷ 8 = 1 remainder 0; 1 ÷ 8 = 0 remainder 1. Reading remainders bottom-up gives 107 in base 8.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0047', 'Mathematics', 'Matrices and determinants', 'Matrix Transpose', NULL, '[{"weight": 1, "conceptId": "hxtpdp"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "B", "explanation": "[[0,1],[1,0]] keeps c=b=1 instead of c=-b, treating the condition as P^T=P (symmetric) rather than P^T=-P (skew-symmetric).", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "[[0,1],[-1,1]] gets the off-diagonal sign right but incorrectly fills in a nonzero diagonal entry (d=1) instead of recognizing that P^T=-P forces all diagonal entries to be 0.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "[[1,-1],[-1,0]] misplaces the given value b=1 into the diagonal position (a=1) instead of the correct off-diagonal position, confusing which entries the skew-symmetry condition constrains.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A matrix P \(\begin{pmatrix}a & b\\ c & d\end{pmatrix}\) is such that P\(^T\) = - P, where P\(^T\) is the transpose of P. If b = 1, then P is', '[{"label": "A", "text": "\\(\\begin{pmatrix}0 & 1\\\\ -1 & 0\\end{pmatrix}\\)", "isCorrect": true}, {"label": "B", "text": "\\(\\begin{pmatrix}0 & 1\\\\ 1 & 0\\end{pmatrix}\\)", "isCorrect": false}, {"label": "C", "text": "\\(\\begin{pmatrix}0 & 1\\\\ -1 & 1\\end{pmatrix}\\)", "isCorrect": false}, {"label": "D", "text": "\\(\\begin{pmatrix}1 & -1\\\\ -1 & 0\\end{pmatrix}\\)", "isCorrect": false}]'::jsonb, 'A', 'P^T = -P means P is skew-symmetric: diagonal entries are 0 and c=-b. With b=1, c=-1, so P = [[0,1],[-1,0]].', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0048', 'Mathematics', 'Surds', 'Rationalizing the Denominator', NULL, '[{"weight": 1, "conceptId": "ff5e8i"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "(1,-2) swaps the values of m and n, mismatching the rational part with the √6 coefficient after correctly simplifying the expression.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "(-2/5, 1) comes from forgetting to divide the numerator''s constant term by the denominator''s -5 fully, dividing only the √6 term correctly while leaving the rational part unsimplified as -2/5 instead of completing the division to -2.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "(2, 3/5) results from a sign error rationalizing with (√3+2√2) instead of (√3-2√2), which changes the denominator''s sign and garbles both coefficients.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'If \(\frac{(2\sqrt{3}-\sqrt{2})}{(\sqrt{3}+2\sqrt{2})} = m +n\sqrt{6}\), find the values of m and n respectively.', '[{"label": "A", "text": "1, -2", "isCorrect": false}, {"label": "B", "text": "-2, 1", "isCorrect": true}, {"label": "C", "text": "\\(\\frac{-2}{5}\\), 1", "isCorrect": false}, {"label": "D", "text": "2, 3/5", "isCorrect": false}]'::jsonb, 'B', 'Multiply top and bottom by (√3-2√2): denominator becomes 3-8=-5. Numerator: (2√3-√2)(√3-2√2)=6-4√6-√6+4=10-5√6. Dividing by -5 gives -2+√6, so m=-2, n=1.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0049', 'Mathematics', 'Polygons', 'Interior and Exterior Angles', NULL, '[{"weight": 1, "conceptId": "i49kq7"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "8 comes from mis-setting the ratio equation, e.g. solving 3E=360 directly instead of first finding E=60° from interior+exterior=180°, then dividing 360 by 45 instead of 60.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "4 results from using the interior angle sum formula for a different shape or miscomputing E as 90° (a quarter turn) instead of solving 2E+E=180° correctly.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "3 comes from confusing exterior angle 60° with the answer itself (n=E÷20=3) via a miskeyed division, or mistaking the triangle''s exterior angle sum property.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'In a regular polygon, each interior angle doubles its corresponding exterior angle. Find the number of sides of the polygon.', '[{"label": "A", "text": "8", "isCorrect": false}, {"label": "B", "text": "6", "isCorrect": true}, {"label": "C", "text": "4", "isCorrect": false}, {"label": "D", "text": "3", "isCorrect": false}]'::jsonb, 'B', 'Interior + exterior = 180° always. If interior = 2×exterior, then 2E+E=180°, so E=60°. Number of sides n = 360°/E = 360/60 = 6.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0050', 'Mathematics', 'Integration', 'Finding a Function from Its Derivative', NULL, '[{"weight": 1, "conceptId": "1n8mtz"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "B", "explanation": "The truncated option (a scraping artifact) reflects a student who integrated only the 3x term and dropped the +2 term''s antiderivative, leaving the expression incomplete.", "misconceptionId": "missing_prerequisite"}, {"option": "C", "explanation": "The truncated option reflects forgetting to divide the 3x^2 coefficient by 2 when integrating 3x (writing 3x^2 instead of 3x^2/2), a common power-rule slip.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "The truncated option reflects the same incomplete integration as C, differing only in how the scraper mangled the trailing terms, but stemming from the same missed division-by-new-exponent step.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A function f(x) passes through the origin and its first derivative is 3x + 2. What is f(x)?', '[{"label": "A", "text": "y =  \\(\\frac{3x^2}{2}\\) + 2x", "isCorrect": true}, {"label": "B", "text": "y = (3x", "isCorrect": false}, {"label": "C", "text": "y = 3x", "isCorrect": false}, {"label": "D", "text": "y = 3x", "isCorrect": false}]'::jsonb, 'A', 'Integrating f''(x)=3x+2 gives f(x) = (3/2)x^2 + 2x + C. Since f(x) passes through the origin, f(0)=0 gives C=0, so f(x) = (3x^2)/2 + 2x.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0051', 'Mathematics', 'Fractions, decimals and approximations', 'Significant Figures', NULL, '[{"weight": 1, "conceptId": "x272hp"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "0.056 results from a small rounding slip in the intermediate division (e.g. rounding 0.055357... up at an earlier step instead of carrying full precision to the final 2 s.f. rounding).", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "0.054 comes from rounding one of the 2-s.f. values differently, e.g. treating 1.063 as 1.0 instead of 1.1, which shifts the final quotient down slightly.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "0.54 is off by a factor of 10, from a decimal place / power-of-ten slip when combining the 10^-3 and 10^-2 exponents (e.g. adding instead of subtracting the powers of 10).", "misconceptionId": "unit_conversion_error"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Evaluate \(\frac{(2.813 \times 10^{-3} \times 1.063)}{(5.637 \times 10^{-2})}\) reducing each number to two significant figures and leaving your answer in two significant figures.', '[{"label": "A", "text": "0.056", "isCorrect": false}, {"label": "B", "text": "0.055", "isCorrect": true}, {"label": "C", "text": "0.054", "isCorrect": false}, {"label": "D", "text": "0.54", "isCorrect": false}]'::jsonb, 'B', 'Rounding each number to 2 s.f.: 2.813×10^-3 → 2.8×10^-3; 1.063 → 1.1; 5.637×10^-2 → 5.6×10^-2. Then (2.8×10^-3 × 1.1)/(5.6×10^-2) = 3.08×10^-3/5.6×10^-2 = 0.055 (2 s.f.).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0052', 'Mathematics', 'Sets', 'Venn Diagram Word Problems', NULL, '[{"weight": 1, "conceptId": "oevb9o"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "8 is the number who like neither type of music, not the number who like only one type.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "24 is the number who like both types, mistaken for those who like only one.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "86 comes from 94 minus the 8 who like neither, forgetting to also exclude those who like both.", "misconceptionId": "missing_prerequisite"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'In a youth club with 94 members, 60 like modern music, and 50 like traditional music. The number of members who like both traditional and modern music is three times those who do not like any type of music. How many members like only one type of music?', '[{"label": "A", "text": "8", "isCorrect": false}, {"label": "B", "text": "24", "isCorrect": false}, {"label": "C", "text": "62", "isCorrect": true}, {"label": "D", "text": "86", "isCorrect": false}]'::jsonb, 'C', 'Let neither=n, both=3n. |M∪T|=60+50-3n=110-3n; total=110-3n+n=94 gives n=8, both=24. Only one type = 110-3n-3n... precisely (M+T-2×both)=110-48=62.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0053', 'Mathematics', 'Binary operations', 'Solving Binary Operation Equations', NULL, '[{"weight": 1, "conceptId": "oaedoe"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "''1, -1'' comes from mistakenly factoring as a²-1=0 instead of the correct quadratic a²+a-2=0.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "''1, 2'' comes from a sign error while rearranging the equation into standard quadratic form.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "''2, -2'' comes from misreading a*2=a² as a*2=2a and solving a different equation.", "misconceptionId": "misunderstood_terminology"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'A binary operation * is defined by a * b = a\(^b\). If a * 2 = 2 - a, find the possible values of a.', '[{"label": "A", "text": "1, -1", "isCorrect": false}, {"label": "B", "text": "1, 2", "isCorrect": false}, {"label": "C", "text": "2, -2", "isCorrect": false}, {"label": "D", "text": "1, -2", "isCorrect": true}]'::jsonb, 'D', 'a*2 = a² by the definition. Setting a²=2-a gives a²+a-2=0, which factors as (a+2)(a-1)=0, so a=1 or a=-2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0054', 'Mathematics', 'Geometric progression', 'Sum to Infinity', NULL, '[{"weight": 1, "conceptId": "cve6pr"}]'::jsonb, '{}', 2, 'application', 90, 'low', 'moderate', '[{"option": "A", "explanation": "2/3 results from a sign slip, computing 1-1/3 instead of 1/3-1.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "Zero results from mistakenly assuming the infinite series sums to exactly 1.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "-1 results from ignoring the series sum entirely and just using -1 as if the bracket were zero.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Evaluate (\(\frac{1}{2} - \frac{1}{4} + \frac{1}{8} - \frac{1}{16} + ...) -1\)', '[{"label": "A", "text": "2/3", "isCorrect": false}, {"label": "B", "text": "zero", "isCorrect": false}, {"label": "C", "text": "-2/3", "isCorrect": true}, {"label": "D", "text": "-1", "isCorrect": false}]'::jsonb, 'C', 'This is a geometric series with first term 1/2 and ratio -1/2, so its sum to infinity is (1/2)/(1-(-1/2)) = 1/3. Then 1/3 - 1 = -2/3.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0055', 'Mathematics', 'Integration', 'Definite Integrals with Trigonometric Identities', NULL, '[{"weight": 1, "conceptId": "5n8i4p"}]'::jsonb, '{}', 3, 'application', 90, 'low', 'heavy', '[{"option": "A", "explanation": "π results from a sign error, treating the integrand as +1 instead of -1.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "π/2 results from mistakenly integrating over [0, π/2] instead of the given [0, π].", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "-π/2 combines both the sign error''s opposite and the wrong interval length.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2000, 'JAMB', '{}', 'Find the value of \(\int^{\pi}_{0}\frac{cos^{2}\theta-1}{sin^{2}\theta}d\theta\)', '[{"label": "A", "text": "π", "isCorrect": false}, {"label": "B", "text": "π/2", "isCorrect": false}, {"label": "C", "text": "-π/2", "isCorrect": false}, {"label": "D", "text": "-π", "isCorrect": true}]'::jsonb, 'D', 'cos²θ - 1 = -sin²θ (Pythagorean identity), so the integrand simplifies to -sin²θ/sin²θ = -1. Integrating -1 from 0 to π gives -π.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb);